"""Build seasonal landing pages using the site's existing SEO layout and assets."""
from pathlib import Path
import html,json,re
from seo_markup import add_markup
ROOT=Path(__file__).resolve().parents[1]
BASE='https://lakehousedalarna.com/'
PAIRS=[{'en':'sweden-lake-house.html','de':'de/ferienhaus-schweden.html'},{'en':'ski-holiday-sweden.html','de':'de/skiurlaub-schweden.html'}]
PAGES=[
 dict(lang='en',path=PAIRS[0]['en'],pair=0,title='Lake House in Sweden with Private Beach & Sauna | Dalarna',description='Stay beside Lake Rogsjön in Dalarna: a private beach, sauna, boat and SUP, three bedrooms and space for six. Plan your Swedish summer and enquire directly.',h1='Lake house in Sweden with private beach and sauna',tag='SUMMER IN DALARNA',hero='images/hero.png',intro='Lake House Dalarna, also known as Solsidan Dalarna, is a private holiday home directly beside Lake Rogsjön in central Sweden. With around 200 m², three bedrooms and room for up to six guests, it is a place for families and small groups to slow down together.',sections=[
 ('A Swedish summer at your own pace','The private sandy beach is approximately 25 metres from the house. Start with a swim, take breakfast on the terrace and leave the afternoon open for a boat trip or time in the forest. A boat and SUP are available for days on the lake; the private sauna and relaxation area offer a warm ending to the day.'),
 ('Space for the whole family','There is room to gather in the open living and dining areas, and three bedrooms when everyone needs a quieter moment. A fully equipped kitchen and washing machine make longer stays practical. The house welcomes a maximum of six guests, including children. A high chair is available and a cot can be requested. As the house is beside the water, children need supervision near the lake.'),
 ('Discover Dalarna beyond the beach','Falun is approximately 25 minutes away by car, with town life and the historic Falu Mine. Bjursås Berg & Sjö is around 20 minutes away, while Leksand Sommarland is about 40 minutes away. Mix days by the water with local excursions, or simply spend more time at the house.'),
 ('Arriving from Stockholm or Arlanda','Stockholm and Stockholm Arlanda Airport are approximately three hours away by car. These are approximate driving times; plan your route for your arrival time and allow for stops and traffic. A car makes it easier to explore the area from the house.')],cards=[('images/private-beach.jpg','The private sandy beach and jetty beside Lake Rogsjön','Your own sandy beach','Swim, sit by the water or enjoy the lake view from the house.'),('images/4.%20Bastu%20och%20relax.png','Private sauna and relaxation area at Solsidan Dalarna','Sauna evenings','A private place to unwind after a day outdoors.'),('images/site/boat-included-2026.png','The boat with its Mercury outboard motor','Time on the lake','Boat and life jackets are included. Guests pay for petrol and refill it before departure.')],faqs=[('Is this a private house or shared accommodation?','You book the whole house for your group, with three bedrooms and a maximum of six guests.'),('How close is the beach?','The private sandy beach is approximately 25 metres from the house, directly on Lake Rogsjön.'),('Are the sauna, boat and SUP available?','The house has a private sauna and relaxation area. A boat and SUP are available; guests pay for the petrol used by the motorboat.'),('Can first-time guests request a direct booking?','Yes. Choose your dates and guests, then send a booking request. Your host reviews the request personally; your stay is confirmed only after you receive a booking confirmation.')]),
 dict(lang='en',path=PAIRS[1]['en'],pair=1,title='Family Ski Holiday in Sweden | Lake House in Dalarna',description='Combine family skiing at Bjursås with a private lakeside house near Falun. Three bedrooms, sauna and space for six. Not ski-in/ski-out; enquire directly.',h1='Family ski holidays in Sweden',tag='WINTER IN DALARNA',hero='images/site/frozen-lake.jpg',intro='Spend the day skiing and return to your own spacious house beside Lake Rogsjön. Solsidan Dalarna combines winter outings with a private sauna, a fireplace and lake views, with around 200 m² and three bedrooms for up to six guests.',sections=[
 ('Skiing nearby, a private house by the lake','This is a lakeside base for a winter holiday, not ski-in/ski-out accommodation. You travel by car to the ski areas and return to a quieter setting after the slopes. Bjursås Berg & Sjö, around 20 minutes away, is the nearby option for a family ski day.'),
 ('Plan your ski days around the conditions','Romme Alpin is another option, approximately 40 minutes away by car. Lugnet ski stadium in Falun is around 25 minutes away, and Sörskog is another local option for cross-country skiing. Check the operators’ current opening dates, snow conditions, lessons and equipment rental before planning each outing. Travel times vary, particularly in winter.'),
 ('Winter beyond the slopes','Enjoy the snowy lakeside setting, time in the sauna and long evenings around the fireplace. The house’s winter photographs show sledding and skating in front of the house when ice conditions allow. Snow and natural ice are never guaranteed; ask about current conditions and do not treat a frozen-looking lake as safe to use.'),
 ('Room for family evenings','The whole house is yours: prepare dinner in the kitchen, gather in the living room and settle into three bedrooms. The washing machine is useful after outdoor days. A maximum of six guests, including children, keeps the stay suited to a family or small group. Stockholm and Arlanda are approximately three hours away by car; allow more time for winter travel.')],cards=[('images/site/winter-window.png','Winter lake view through the windows of the house','A warm place to return to','Enjoy the lake landscape from the comfort of the house.'),('images/4.%20Bastu%20och%20relax.png','Private sauna and relaxation area','Your own sauna','Unwind together after a day outdoors.'),('images/site/bjursas-piste-map.jpg','Piste map of Bjursås Berg & Sjö','Explore Bjursås','Plan the day with the ski area’s current information.')],faqs=[('Is the house ski-in/ski-out?','No. Solsidan Dalarna is a private house beside Lake Rogsjön. A car is needed to reach the nearby ski areas.'),('How far is Bjursås from the house?','Bjursås Berg & Sjö is approximately 20 minutes away by car. Allow extra time when winter road conditions require it.'),('Are snow and skating guaranteed?','No. Snow and natural lake ice depend on the weather. Skating is only an option when current ice conditions have been assessed as safe.'),('Can a family book directly for the first visit?','Yes. First-time and returning guests can send a direct request. The host reviews it personally and confirms the booking separately.')]),
 dict(lang='de',path=PAIRS[1]['de'],pair=1,title='Skiurlaub in Schweden | Ferienhaus in Dalarna mit Sauna',description='Familien-Skiurlaub mit privatem Ferienhaus am Rogsjön: drei Schlafzimmer, Sauna und Platz für sechs. Bjursås ca. 20 Autominuten entfernt. Direkt anfragen.',h1='Skiurlaub in Schweden, zuhause am See',tag='WINTER IN DALARNA',hero='images/site/frozen-lake.jpg',intro='Tagsüber gemeinsam Ski fahren, abends in die eigene Sauna: Solsidan Dalarna ist ein privates Ferienhaus am Rogsjön in Mittelschweden. Rund 200 m², drei Schlafzimmer und Platz für bis zu sechs Gäste verbinden Wintertage in der Natur mit entspannten Stunden im Haus.',sections=[
 ('Skifahren in der Nähe, wohnen direkt am See','Das Haus liegt nicht an der Piste und ist keine Ski-in/Ski-out-Unterkunft. Sie fahren mit dem Auto ins Skigebiet und kehren anschließend an den See zurück. Bjursås Berg & Sjö liegt etwa 20 Autominuten entfernt und bietet sich für einen gemeinsamen Skitag mit der Familie an.'),
 ('Den Skitag nach Wetter und Schneelage planen','Romme Alpin ist eine weitere Möglichkeit; die Fahrt dauert ungefähr 40 Minuten. Das Skistadion Lugnet in Falun erreichen Sie in etwa 25 Minuten. Für Langlauf kommt auch Sörskog infrage. Informieren Sie sich bei den jeweiligen Betreibern über Öffnungszeiten, Schneelage, Skikurse und Ausrüstung. Gerade im Winter können die Fahrzeiten abweichen.'),
 ('Winterurlaub auch abseits der Pisten','Nach einem Tag draußen warten die private Sauna, der Kamin und der Blick auf den See. Unsere Winterbilder zeigen Rodeln im Schnee und Schlittschuhlaufen vor dem Haus bei geeigneten Eisverhältnissen. Schnee und tragfähiges Natureis sind nicht garantiert. Erkundigen Sie sich nach den aktuellen Bedingungen; eine gefrorene Oberfläche allein bedeutet nicht, dass der See sicher betreten werden kann.'),
 ('Platz für gemeinsame Abende','Kochen Sie zusammen in der Küche, machen Sie es sich im Wohnzimmer gemütlich und genießen Sie die Ruhe am See. Drei Schlafzimmer und eine Waschmaschine erleichtern den Familienurlaub. Das Haus bietet Platz für insgesamt sechs Gäste, Kinder eingeschlossen. Stockholm und der Flughafen Arlanda liegen ungefähr drei Autostunden entfernt; planen Sie im Winter zusätzliche Zeit ein.')],cards=[('images/site/winter-window.png','Blick aus dem Ferienhaus auf den winterlichen Rogsjön','Zurück ins warme Haus','Die Winterlandschaft ganz in Ruhe vom Wohnzimmer aus genießen.'),('images/4.%20Bastu%20och%20relax.png','Private Sauna mit Relaxbereich im Ferienhaus','Sauna am Abend','Entspannen nach einem Tag an der frischen Luft.'),('images/site/bjursas-piste-map.jpg','Pistenplan von Bjursås Berg & Sjö','Bjursås entdecken','Nutzen Sie die aktuellen Informationen des Skigebiets zur Planung.')],faqs=[('Liegt das Haus direkt an der Skipiste?','Nein. Solsidan Dalarna liegt am Rogsjön. Die nahe gelegenen Skigebiete erreichen Sie mit dem Auto; das Haus bietet keinen Ski-in/Ski-out-Zugang.'),('Wie weit ist Bjursås entfernt?','Bjursås Berg & Sjö liegt etwa 20 Autominuten vom Haus entfernt. Bei winterlichen Straßenverhältnissen sollten Sie mehr Zeit einplanen.'),('Sind Schnee und Schlittschuhlaufen garantiert?','Nein. Schnee und Natureis hängen vom Wetter ab. Schlittschuhlaufen ist nur bei aktuell als sicher beurteilten Eisverhältnissen möglich.'),('Können wir auch beim ersten Aufenthalt direkt anfragen?','Ja. Neue und wiederkehrende Gäste können direkt eine Buchungsanfrage senden. Ihr Gastgeber prüft diese persönlich und bestätigt die Buchung anschließend separat.')])]

def alternates(pair):
 return ''.join(f'<link rel="alternate" hreflang="{lang}" href="{BASE+route}">' for lang,route in pair.items())+f'<link rel="alternate" hreflang="x-default" href="{BASE+pair["en"]}">'

def render(d):
 e=html.escape;de=d['lang']=='de';lang=d['lang'];home='/de/' if de else '/en/';house=home+('ferienhaus/' if de else 'house/');book=home+('buchen/' if de else 'booking/');pair=PAIRS[d['pair']];other=PAIRS[1-d['pair']][lang]
 cta='Verfügbarkeit & Preise' if de else 'Check availability & rates';request='Buchungsanfrage senden' if de else 'Send a booking request';houselabel='Das Haus' if de else 'The house';start='Startseite' if de else 'Home';gallery='Bilder' if de else 'Gallery';region='Dalarna entdecken' if de else 'Explore Dalarna';otherlabel=('Sommer am See' if d['pair'] else 'Winter und Skifahren') if de else ('Summer by the lake' if d['pair'] else 'Winter and skiing')
 sections=''.join('<section class="seo-section"><div class="seo-intro"><h2>'+e(h)+'</h2><p>'+e(t)+'</p></div></section>' for h,t in d['sections'])
 cards='<section class="seo-section"><div class="seo-feature-grid">'+''.join(f'<article><img src="/{src}" alt="{e(alt)}" loading="lazy" decoding="async"><h2>{e(h)}</h2><p>{e(t)}</p></article>' for src,alt,h,t in d['cards'])+'</div></section>'
 faq='<section class="guest-faq seo-section" id="guest-questions"><h2>'+('Fragen zu Ihrem Aufenthalt' if de else 'Questions before your stay')+'</h2>'+''.join('<details><summary>'+e(q)+'</summary><p>'+e(a)+'</p></details>' for q,a in d['faqs'])+'</section>'
 trust='Gäste-Favorit auf Airbnb. Lesen Sie die Erfahrungen unserer Gäste.' if de else 'An Airbnb Guest Favourite. Read what our guests say about their stays.'
 confirm='Auch für Ihren ersten Aufenthalt können Sie direkt anfragen. Wir prüfen Ihre Anfrage persönlich. Erst unsere Buchungsbestätigung bestätigt Ihren Aufenthalt.' if de else 'You are welcome to enquire directly for your first stay or a return visit. We review your request personally. Your stay is confirmed only when you receive our booking confirmation.'
 airbnb='Sie buchen lieber über Airbnb? Solsidan Dalarna finden Sie auch dort.' if de else 'Prefer to book through Airbnb? Solsidan Dalarna is also available there.'
 links=f'<a href="{home}">{start}</a><a href="{house}">{houselabel}</a><a href="{home}#gallery">{gallery}</a><a href="{home}#explore">{region}</a><a href="/{other}">{otherlabel}</a><a href="{house}#guest-questions">FAQ</a><a href="{book}">{e(cta)}</a>'
 result=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(d['title'])}</title><meta name="description" content="{e(d['description'])}"><link rel="canonical" href="{BASE+d['path']}">{alternates(pair)}<meta property="og:title" content="{e(d['title'])}"><meta property="og:description" content="{e(d['description'])}"><meta property="og:url" content="{BASE+d['path']}"><meta property="og:type" content="website"><meta property="og:locale" content="{'de_DE' if de else 'en_GB'}"><meta property="og:image" content="{BASE+d['hero']}"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/style.css?v=20260924-mobile-layout"><link rel="stylesheet" href="/fonts-local.css"><link rel="stylesheet" href="/consent.css?v=20260924-auto-map"><script defer src="/analytics-consent.js?v=20260924-seo"></script></head><body class="seo-page"><header class="request-header"><nav class="navbar"><a class="logo" href="{home}"><div class="logo-title">Lake House Dalarna</div><div class="logo-subtitle">Solsidan Dalarna</div></a><ul class="menu"><li><a href="{home}">{start}</a></li><li><a href="{house}">{houselabel}</a></li><li><a class="book-btn" href="{book}">{e(cta)}</a></li></ul><div class="mobile-quick-nav"><a href="{home}">{start}</a><a href="{home}#gallery">{gallery}</a><a href="{house}">{houselabel}</a></div><div class="language-switcher" aria-label="Language"><a href="/{pair['en']}" lang="en" aria-label="English"><span class="flag flag-en" aria-hidden="true"></span><small>EN</small></a><a href="/sv/" lang="sv" aria-label="Svenska"><span class="flag flag-sv" aria-hidden="true"></span><small>SV</small></a><a href="/{pair['de']}" lang="de" aria-label="Deutsch"><span class="flag flag-de" aria-hidden="true"></span><small>DE</small></a></div></nav></header><main><section class="seo-hero" style="background-image:url('/{d['hero']}')"><div class="seo-hero-overlay"></div><div class="seo-hero-content"><p class="welcome">{d['tag']}</p><h1>{e(d['h1'])}</h1><p>{e(d['intro'])}</p><div class="hero-buttons"><a class="primary-btn" href="{book}">{e(cta)}</a><a class="secondary-btn" href="{house}">{houselabel}</a></div></div></section>{sections[:sections.index('</section>')+10]}{cards}{sections[sections.index('</section>')+10:]}<section class="seo-section"><h2>{'Planen Sie Ihren Aufenthalt' if de else 'Plan your stay'}</h2><p>{confirm}</p><p><a href="{home}#reviews">{trust}</a></p><a class="primary-btn" href="{book}">{request}</a><p class="booking-review-link"><a href="https://airbnb.com/h/solsidan-dalarna" target="_blank" rel="noopener noreferrer">{airbnb}</a></p><p><a href="https://wa.me/46703021094">{'Fragen? Schreiben Sie uns auf WhatsApp' if de else 'Questions? Chat with us on WhatsApp'}</a></p></section>{faq}<section class="seo-section"><h2>{'Mehr entdecken' if de else 'Explore your stay'}</h2><div class="footer-links">{links}</div><p><a href="https://bjursas.com/">Bjursås Berg &amp; Sjö</a> · <a href="https://www.rommealpin.se/en/">Romme Alpin</a></p></section></main><footer><div class="footer-content"><h2>Lake House Dalarna</h2><p>Solsidan Dalarna · Rogsjön · Sweden</p><div class="footer-links">{links}</div><p class="copyright">© 2026 Lake House Dalarna</p></div></footer><script src="/navigation.js?v=20260917-nav-spacing"></script></body></html>'''
 return add_markup(result,lang,BASE+d['path'],d['title'],d['description'])

def build():
 for d in PAGES:(ROOT/d['path']).write_text(render(d),encoding='utf-8')
 # Keep the established German URL and original content/layout.
 d=ROOT/'content/de-summer.html';result=d.read_text(encoding='utf-8')
 result=result.replace('</head>',alternates(PAIRS[0])+'</head>')
 title=html.unescape(re.search('<title>(.*?)</title>',result)[1]);desc=html.unescape(re.search('name="description" content="([^"]+)"',result)[1])
 (ROOT/PAIRS[0]['de']).write_text(add_markup(result,'de',BASE+PAIRS[0]['de'],title,desc),encoding='utf-8')
if __name__=='__main__':build()
